// for overlong unfinished spans. This preserves the previously useful
// parser-validity and close/repair mechanics while changing the causal axis
// from mostly token-wise/free generation to proactive symbol-level answer
// construction.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Open branch: OpenConstrainedSpan sets insideConstrainedOut := true and
//   currentConstrainedOut := [], which is parser-valid by the precondition
//   parser.IsValidPrefix([]).
// - Close branch: CloseConstrainedSpan exits constrained mode and clears the
//   constrained prefix, so the implication is vacuous afterward.
// - Repair branch: RollbackConstrainedSuffix returns a repaired constrained
//   prefix that is parser-valid, so keeping insideConstrainedOut := true
//   preserves parser_validity.
// - Narrow constrained branch: SafeRepetitionPenaltyStep returns either EOS or
//   a token whose extension preserves parser validity; on non-EOS,
//   AppendConstrainedToken commits exactly that valid extension.
// - Broad constrained branch: ConstrainedSymbolInGenerated returns currentOut
//   that is parser-valid; assigning currentConstrainedOut := currentOut
//   therefore preserves the invariant.
// 
// progress:
// - Open branch: OpenConstrainedSpan consumes one token-step and appends only
//   the visible delimiter, so visible growth is at most the charged budget.
// - Close branch: CloseConstrainedSpan consumes one token-step and appends at
//   most one visible close delimiter.
// - Repair branch: RollbackConstrainedSuffix consumes no LM token and only
//   shrinks or preserves visible output; charging one loop step still preserves
//   |generated| <= |generatedPrefix| + steps.
// - Narrow constrained branch: SafeRepetitionPenaltyStep consumes one
//   token-step; EOS may append nothing, while a non-EOS token is appended once
//   via AppendConstrainedToken, so visible growth is at most one.
// - Broad constrained branch: ConstrainedSymbolInGenerated consumes stepsUsed
//   token-steps and may accept only the longest valid visible prefix of the LM
//   chunk; therefore visible growth is at most stepsUsed, preserving the bound
//   after steps := steps + stepsUsed.
// 
// Termination/decreases:
// - Every loop iteration either breaks or increases `steps` by at least 1.
//   Thus under guard `steps < maxSteps`, the measure `maxSteps - steps`
//   strictly decreases on every back-edge.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 8;
var rollbackLimit: nat := 64;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
    generated := openedGenerated;
    insideConstrainedOut := openedInside;
    currentConstrainedOut := openedCurrent;
    steps := steps + 1;
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= rollbackLimit {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

    if validCount <= narrowThreshold {
      var next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    } else {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget == 0 || stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolOut, hitEos, stepsUsed := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      insideConstrainedOut := true;
      currentConstrainedOut := symbolOut;
      steps := steps + stepsUsed;
      if hitEos {
        break;
      }
    }
  }
}

