//   so visible growth is at most the consumed budget.
// - Soft-step branch: SafeSoftConstrainedStep consumes one token-step; EOS may
//   append nothing, and a non-EOS result appends at most one token, so the bound
//   is preserved.
// - Penalized fallback branch: SafePenalizedConstrainedStep consumes one
//   token-step; again, visible growth is at most one token and therefore at most
//   the increment to steps.
//
// Termination/decreases:
// - Every loop back-edge either breaks or increases steps by at least 1, so
//   maxSteps - steps strictly decreases on each iteration.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 6;
var rollbackLimit: nat := 48;
var penaltyTokens := [".", "<<", ">>"];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
    generated := openedGenerated;
    insideConstrainedOut := openedInside;
    currentConstrainedOut := openedCurrent;
    steps := steps + 1;
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else if |currentConstrainedOut| >= rollbackLimit {
    var rolledGenerated, rolledCurrent := helpers.RollbackConstrainedSuffix(
      parser, generated, currentConstrainedOut
    );
    generated := rolledGenerated;
    insideConstrainedOut := true;
    currentConstrainedOut := rolledCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

    if validCount <= narrowThreshold {
      var candidates := helpers.TopValidCandidates(
        lm, parser, constrainedPrompt, currentConstrainedOut, 4, eosToken
      );
      steps := steps + 1;

      var next := eosToken;
      if |candidates| > 0 {
        next := candidates[0];
        if next == eosToken && |candidates| > 1 {
          next := candidates[1];
        }
      }

      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    } else {
      var nextSoft, usedFallback := helpers.SafeSoftConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 8.0, eosToken
      );
      steps := steps + 1;

      if nextSoft == eosToken {
        break;
      } else if usedFallback {
        var nextPen := helpers.SafePenalizedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, penaltyTokens, 4.0, eosToken
        );
        if steps < maxSteps {
          steps := steps + 1;
          if nextPen == eosToken {
            break;
          } else {
            var appendedGenerated2, appendedInside2, appendedCurrent2 := helpers.AppendConstrainedToken(
              lm, parser, generated, currentConstrainedOut, nextPen
            );
            generated := appendedGenerated2;
            insideConstrainedOut := appendedInside2;
            currentConstrainedOut := appendedCurrent2;
          }
        } else {
          break;
        }
      } else {
        var appendedGenerated3, appendedInside3, appendedCurrent3 := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, nextSoft
        );
        generated := appendedGenerated3;
        insideConstrainedOut := appendedInside3;
        currentConstrainedOut := appendedCurrent3;
      }
    }
  }
}

cost := steps;
